	mockHandler := &http.Handler{
		Handler: func(w http.ResponseWriter, req *http.Request) {
			w.WriteHeader(http.StatusOK)
		},
	}

	// Create a mock server
	server := httptest.NewServer(mockHandler)
	defer server.Close()

	// Create a test client
