	filteredServer := mux_discovery_complete.WithMuxAndDiscoveryComplete(mockHandler, muxAndDiscoveryCompleteSignal)

	// Create a new test client
	testClient := http.Client{}
	testReq := http.Request{}

	// Make a request before the server is ready
	testClient.Get(server.URL)
	time.Sleep(500 * time.Millisecond)

	// Make a request after the server is ready
	testClient.Get(server.URL)

	// Check if the context has the protection key
	ctx, _ := testClient.Get(context.Background())
	if !noMuxAndDiscoveryIncompleteKey(ctx) {
		t.Errorf("Expected no protection key in context")
	}

	// Check if the context has the protection key
	ctx, _ = testClient.Get(context.Background())
	if noMuxAndDiscoveryIncompleteKey(ctx) {
		t.Errorf("Expected protection key in context")
	}
}

